-- Optimize auth function evaluation in RLS policies by evaluating identity/JWT once per statement.
DROP POLICY IF EXISTS borradores_correo_delete_own ON public.borradores_correo_usuario;
CREATE POLICY borradores_correo_delete_own ON public.borradores_correo_usuario FOR DELETE TO authenticated USING (usuario_es_admin_principal_2026() OR lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'') ));
DROP POLICY IF EXISTS borradores_correo_insert_own ON public.borradores_correo_usuario;
CREATE POLICY borradores_correo_insert_own ON public.borradores_correo_usuario FOR INSERT TO authenticated WITH CHECK (usuario_es_admin_principal_2026() OR lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'') ));
DROP POLICY IF EXISTS borradores_correo_select_own ON public.borradores_correo_usuario;
CREATE POLICY borradores_correo_select_own ON public.borradores_correo_usuario FOR SELECT TO authenticated USING (usuario_es_admin_principal_2026() OR lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'') ));
DROP POLICY IF EXISTS borradores_correo_update_own ON public.borradores_correo_usuario;
CREATE POLICY borradores_correo_update_own ON public.borradores_correo_usuario FOR UPDATE TO authenticated USING (usuario_es_admin_principal_2026() OR lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'') )) WITH CHECK (usuario_es_admin_principal_2026() OR lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'') ));
DROP POLICY IF EXISTS control_sesion_global_read_authenticated ON public.control_sesion_global;
CREATE POLICY control_sesion_global_read_authenticated ON public.control_sesion_global FOR SELECT TO authenticated USING ((select auth.uid()) IS NOT NULL);
DROP POLICY IF EXISTS "Users can insert own UI preferences" ON public.user_ui_preferences;
CREATE POLICY "Users can insert own UI preferences" ON public.user_ui_preferences FOR INSERT TO authenticated WITH CHECK ((select auth.uid()) = user_id);
DROP POLICY IF EXISTS "Users can read own UI preferences" ON public.user_ui_preferences;
CREATE POLICY "Users can read own UI preferences" ON public.user_ui_preferences FOR SELECT TO authenticated USING ((select auth.uid()) = user_id);
DROP POLICY IF EXISTS "Users can update own UI preferences" ON public.user_ui_preferences;
CREATE POLICY "Users can update own UI preferences" ON public.user_ui_preferences FOR UPDATE TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
DROP POLICY IF EXISTS rrhh_bitacora_insert_2026 ON public.rrhh_bitacora;
CREATE POLICY rrhh_bitacora_insert_2026 ON public.rrhh_bitacora FOR INSERT TO authenticated WITH CHECK ((user_id=(select auth.uid())) AND ((visibilidad='PERSONAL') OR usuario_es_admin_principal_2026() OR usuario_tiene_alguno_permiso(ARRAY['espacio','tareas']::text[])));
DROP POLICY IF EXISTS rrhh_bitacora_select_2026 ON public.rrhh_bitacora;
CREATE POLICY rrhh_bitacora_select_2026 ON public.rrhh_bitacora FOR SELECT TO authenticated USING ((user_id=(select auth.uid())) OR ((visibilidad='COMPARTIDA') AND (usuario_es_admin_principal_2026() OR usuario_tiene_alguno_permiso(ARRAY['espacio','tareas']::text[]))));
DROP POLICY IF EXISTS rrhh_notas_delete_2026 ON public.rrhh_notas;
CREATE POLICY rrhh_notas_delete_2026 ON public.rrhh_notas FOR DELETE TO authenticated USING ((user_id=(select auth.uid())) OR usuario_es_admin_principal_2026());
DROP POLICY IF EXISTS rrhh_notas_insert_2026 ON public.rrhh_notas;
CREATE POLICY rrhh_notas_insert_2026 ON public.rrhh_notas FOR INSERT TO authenticated WITH CHECK ((user_id=(select auth.uid())) AND ((visibilidad='PERSONAL') OR usuario_es_admin_principal_2026() OR usuario_tiene_alguno_permiso(ARRAY['espacio','tareas']::text[])));
DROP POLICY IF EXISTS rrhh_notas_select_2026 ON public.rrhh_notas;
CREATE POLICY rrhh_notas_select_2026 ON public.rrhh_notas FOR SELECT TO authenticated USING ((user_id=(select auth.uid())) OR ((visibilidad='COMPARTIDA') AND (usuario_es_admin_principal_2026() OR usuario_tiene_alguno_permiso(ARRAY['espacio','tareas']::text[]))));
DROP POLICY IF EXISTS rrhh_notas_update_2026 ON public.rrhh_notas;
CREATE POLICY rrhh_notas_update_2026 ON public.rrhh_notas FOR UPDATE TO authenticated USING ((user_id=(select auth.uid())) OR usuario_es_admin_principal_2026()) WITH CHECK (((user_id=(select auth.uid())) OR usuario_es_admin_principal_2026()) AND ((visibilidad='PERSONAL') OR usuario_es_admin_principal_2026() OR usuario_tiene_alguno_permiso(ARRAY['espacio','tareas']::text[])));
DROP POLICY IF EXISTS tareas_select_scope ON public.tareas;
CREATE POLICY tareas_select_scope ON public.tareas FOR SELECT TO authenticated USING (usuario_es_admin_principal_2026() OR (usuario_tiene_alguno_permiso(ARRAY['tareas']::text[]) AND ((responsable_rol_id=usuario_rol_actual_id()) OR (revisor_rol_id=usuario_rol_actual_id()) OR (lower(creado_por_email)=lower(coalesce(((select auth.jwt())->>'email'),''))))));
DROP POLICY IF EXISTS tareas_eventos_insert_scope ON public.tareas_eventos;
CREATE POLICY tareas_eventos_insert_scope ON public.tareas_eventos FOR INSERT TO authenticated WITH CHECK (usuario_es_admin_principal_2026() OR (usuario_tiene_alguno_permiso(ARRAY['tareas']::text[]) AND lower(usuario_email)=lower(coalesce(((select auth.jwt())->>'email'),'')) AND EXISTS (SELECT 1 FROM public.tareas t WHERE t.id=tareas_eventos.tarea_id AND ((t.responsable_rol_id=usuario_rol_actual_id()) OR (t.revisor_rol_id=usuario_rol_actual_id()) OR lower(t.creado_por_email)=lower(coalesce(((select auth.jwt())->>'email'),''))))));
DROP POLICY IF EXISTS tareas_eventos_select_scope ON public.tareas_eventos;
CREATE POLICY tareas_eventos_select_scope ON public.tareas_eventos FOR SELECT TO authenticated USING (usuario_es_admin_principal_2026() OR (usuario_tiene_alguno_permiso(ARRAY['tareas']::text[]) AND EXISTS (SELECT 1 FROM public.tareas t WHERE t.id=tareas_eventos.tarea_id AND ((t.responsable_rol_id=usuario_rol_actual_id()) OR ((t.revisor_rol_id=usuario_rol_actual_id()) AND EXISTS (SELECT 1 FROM public.usuarios_roles u WHERE u.id=usuario_rol_actual_id() AND u.activo IS TRUE AND u.puede_revisar_tareas IS TRUE)) OR lower(t.creado_por_email)=lower(coalesce(((select auth.jwt())->>'email'),''))))));
DROP POLICY IF EXISTS usuarios_roles_lectura ON public.usuarios_roles;
CREATE POLICY usuarios_roles_lectura ON public.usuarios_roles FOR SELECT TO authenticated USING (usuario_actual_es_admin() OR (auth_user_id=(select auth.uid())) OR (lower(email)=lower(coalesce(((select auth.jwt())->>'email'),''))));
